const SMALL = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
  "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
const TENS = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];

function three(n: number, out: string[]): void {
  if (n >= 100) { out.push(SMALL[Math.floor(n / 100)], "Hundred"); n %= 100; }
  if (n >= 20) { out.push(TENS[Math.floor(n / 10)]); n %= 10; }
  if (n > 0) out.push(SMALL[n]);
}

function spellNumber(num: number): string {
  if (num === 0) return "Zero";
  const out: string[] = [];
  const scales: [number, string][] = [[1e9, "Billion"], [1e6, "Million"], [1e3, "Thousand"], [1, ""]];
  for (const [size, word] of scales) {
    const group = Math.floor(num / size) % 1000;
    if (group === 0) continue;
    three(group, out);
    if (word) out.push(word);
  }
  return out.join(" ");
}

