class Solution:
    def spellNumber(self, num: int) -> str:
        if num == 0:
            return "Zero"

        def three(n, out):
            if n >= 100:
                out += [SMALL[n // 100], "Hundred"]
                n %= 100
            if n >= 20:
                out.append(TENS[n // 10])
                n %= 10
            if n:
                out.append(SMALL[n])

        out = []
        for size, word in ((10**9, "Billion"), (10**6, "Million"), (10**3, "Thousand"), (1, "")):
            group = num // size % 1000
            if group:
                three(group, out)
                if word:
                    out.append(word)
        return " ".join(out)

