function spellNumber(num: number): string {
  const small = ["Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
    "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
  const tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
  const scales: [number, string][] = [[1e9, "Billion"], [1e6, "Million"], [1e3, "Thousand"], [100, "Hundred"]];
  // words for n ≥ 1, as a list
  const go = (n: number): string[] => {
    if (n < 20) return [small[n]];
    if (n < 100) return n % 10 ? [tens[Math.floor(n / 10)], small[n % 10]] : [tens[n / 10]];
    for (const [size, word] of scales) {
      if (n >= size) {
        const head = Math.floor(n / size), rest = n % size;
        return [...go(head), word, ...(rest ? go(rest) : [])];
      }
    }
    return [];
  };
  return go(num).join(" ");
}

