            # words for n >= 1, as a list
            if n < 20:
                return [small[n]]
            if n < 100:
                return [tens[n // 10]] + ([small[n % 10]] if n % 10 else [])
            for size, word in scales:
                if n >= size:
                    head, rest = divmod(n, size)
